mapper.select:
select 

from ETR_PLEDGE
where ENTRUST_ID = #{entrustId,jdbcType=VARCHAR}
  and FINPROD_ID = #{finprodId,jdbcType=VARCHAR}

mapper.delete:
delete from ETR_PLEDGE
where ENTRUST_ID = #{entrustId,jdbcType=VARCHAR}
  and FINPROD_ID = #{finprodId,jdbcType=VARCHAR}

mapper.update:
update ETR_PLEDGE
set PLEDGE_FACE_VALUE = #{pledgeFaceValue,jdbcType=DECIMAL},
    PLEDGE_NUMBER = #{pledgeNumber,jdbcType=DECIMAL},
    PLEDGE_RATIO = #{pledgeRatio,jdbcType=DECIMAL},
    PLEDGE_AMT = #{pledgeAmt,jdbcType=DECIMAL},
    UPDATE_USER = #{updateUser,jdbcType=VARCHAR},
    UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP}
where ENTRUST_ID = #{entrustId,jdbcType=VARCHAR}
  and FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
